begin;
create extension if not exists pgtap with schema extensions;
set search_path to public, extensions;
select plan(36);

insert into auth.users(id,instance_id,aud,role,email,encrypted_password,created_at,updated_at) values
('18200000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','mcp182@example.invalid','x',now(),now());
insert into public.organizations(id,name) values ('18200000-0000-0000-0000-000000000002','Synthetic');
insert into public.organization_members(organization_id,user_id,role) values ('18200000-0000-0000-0000-000000000002','18200000-0000-0000-0000-000000000001','owner');
insert into auth.oauth_clients(id,registration_type,redirect_uris,grant_types,client_type,token_endpoint_auth_method) values ('18200000-0000-0000-0000-000000000003','dynamic','http://localhost/callback','authorization_code','public','none');
insert into auth.oauth_consents(id,user_id,client_id,scopes) values ('18200000-0000-0000-0000-000000000004','18200000-0000-0000-0000-000000000001','18200000-0000-0000-0000-000000000003','openid');
insert into private.mcp_reauth_proofs(user_id,client_id,consent_granted_at,verified_at)
  select user_id,client_id,granted_at,clock_timestamp() from auth.oauth_consents where id='18200000-0000-0000-0000-000000000004';
insert into auth.sessions(id,user_id,oauth_client_id,created_at) values ('18200000-0000-0000-0000-000000000005','18200000-0000-0000-0000-000000000001','18200000-0000-0000-0000-000000000003',now());
insert into public.clients(id,organization_id,name) values ('18200000-0000-0000-0000-000000000006','18200000-0000-0000-0000-000000000002','Synthetic client');
insert into public.form_templates(client_id,schema) values ('18200000-0000-0000-0000-000000000006','[{"id":"note","label":"Note","type":"text"},{"id":"flag","label":"Flag","type":"checkbox"},{"id":"choice","label":"Choice","type":"select","options":"A,B"},{"id":"multi","label":"Multi","type":"multicheckbox","options":"A,B"},{"id":"time","label":"Time","type":"time"},{"id":"number","label":"Number","type":"number"}]');
insert into public.reports(id,client_id,helper_id,service_date,status,start_at,end_at) values ('18200000-0000-0000-0000-000000000007','18200000-0000-0000-0000-000000000006','18200000-0000-0000-0000-000000000001','2026-10-28','draft','2026-10-28 01:00+00','2026-10-28 02:00+00');
insert into public.report_values(report_id,data) values ('18200000-0000-0000-0000-000000000007','{"note":"before"}');
select set_config('request.jwt.claims','{"sub":"18200000-0000-0000-0000-000000000001","role":"mcp_import","exp":4102444800,"client_id":"18200000-0000-0000-0000-000000000003","session_id":"18200000-0000-0000-0000-000000000005"}',true);
insert into private.mcp_record_read_controls(organization_id,enabled,conditions,confirmed_by,confirmed_at) values ('18200000-0000-0000-0000-000000000002',true,'{}','18200000-0000-0000-0000-000000000001',now());

select ok(not has_table_privilege('mcp_import','private.mcp_record_edit_proposals','SELECT'), 'MCP role cannot directly read proposals');
select ok(not has_table_privilege('authenticated','private.mcp_record_edit_proposals','INSERT'), 'browser role cannot directly create proposals');
select ok(not has_function_privilege('mcp_import','private.prepare_mcp_record_edit(uuid,uuid,bigint,jsonb,text,jsonb)','EXECUTE'), 'internal prepare is not directly callable by MCP');
select throws_ok($$select private.prepare_mcp_record_edit('18200000-0000-0000-0000-000000000002','18200000-0000-0000-0000-000000000007',0,'{"note":"after"}','reason')$$,'42501','proposal_unavailable','edit is disabled by default');
insert into private.mcp_record_edit_controls(organization_id,enabled,conditions,confirmed_by,confirmed_at) values ('18200000-0000-0000-0000-000000000002',true,'{}','18200000-0000-0000-0000-000000000001',now());
select throws_ok($$select private.prepare_mcp_record_edit('18200000-0000-0000-0000-000000000002','18200000-0000-0000-0000-000000000007',(select current_version from public.reports where id='18200000-0000-0000-0000-000000000007'),'{"note":"before","unknown":"bad"}','reason')$$,'22023','invalid_record_proposal','unknown changed field rejected');
select throws_ok($$select private.prepare_mcp_record_edit('18200000-0000-0000-0000-000000000002','18200000-0000-0000-0000-000000000007',(select current_version from public.reports where id='18200000-0000-0000-0000-000000000007'),'{"note":true}','reason')$$,'22023','invalid_record_proposal','invalid form field type rejected');
select lives_ok($$select private.prepare_mcp_record_edit('18200000-0000-0000-0000-000000000002','18200000-0000-0000-0000-000000000007',(select current_version from public.reports where id='18200000-0000-0000-0000-000000000007'),'{"note":"before","flag":true,"choice":"A","multi":["B"],"time":"10:30","number":"1.5"}','valid form')$$,'valid custom form field types accepted');
select throws_ok($$select private.prepare_mcp_record_edit('18200000-0000-0000-0000-000000000002','18200000-0000-0000-0000-000000000007',(select current_version from public.reports where id='18200000-0000-0000-0000-000000000007'),'{"note":"before","choice":"C"}','bad option')$$,'22023','invalid_record_proposal','unknown select option rejected');
select throws_ok($$select private.prepare_mcp_record_edit('18200000-0000-0000-0000-000000000002','18200000-0000-0000-0000-000000000007',(select current_version from public.reports where id='18200000-0000-0000-0000-000000000007'),'{"note":"before","multi":["C"]}','bad option')$$,'22023','invalid_record_proposal','unknown multi option rejected');
select throws_ok($$select private.prepare_mcp_record_edit('18200000-0000-0000-0000-000000000002','18200000-0000-0000-0000-000000000007',(select current_version from public.reports where id='18200000-0000-0000-0000-000000000007'),'{"note":"before","time":"25:90"}','bad time')$$,'22023','invalid_record_proposal','invalid form time rejected');
select throws_ok($$select private.prepare_mcp_record_edit('18200000-0000-0000-0000-000000000002','18200000-0000-0000-0000-000000000007',(select current_version from public.reports where id='18200000-0000-0000-0000-000000000007'),'{"note":"before"}','no change')$$,'22023','invalid_record_proposal','no-op proposal rejected');
select throws_ok($$select private.prepare_mcp_record_edit('18200000-0000-0000-0000-000000000002','18200000-0000-0000-0000-000000000007',(select current_version from public.reports where id='18200000-0000-0000-0000-000000000007'),'{"note":"after"}','empty ID','{"actual_service_type_id":""}')$$,'22023','invalid_record_proposal','empty service ID rejected');
savepoint no_status;
update public.reports set status=null where id='18200000-0000-0000-0000-000000000007';
select throws_ok($$select private.prepare_mcp_record_edit('18200000-0000-0000-0000-000000000002','18200000-0000-0000-0000-000000000007',(select current_version from public.reports where id='18200000-0000-0000-0000-000000000007'),'{"note":"after"}','missing status')$$,'42501','proposal_unavailable','null record status is not editable');
rollback to savepoint no_status;
select throws_ok($$select private.prepare_mcp_record_edit('18200000-0000-0000-0000-000000000002','18200000-0000-0000-0000-000000000007',999,'{"note":"after"}','reason')$$,'22023','proposal_changed','stale version is rejected');
select throws_ok($$select private.prepare_mcp_record_edit('18200000-0000-0000-0000-000000000002','18200000-0000-0000-0000-000000000007',(select current_version from public.reports where id='18200000-0000-0000-0000-000000000007'),'{"note":"after"}',' ')$$,'22023','invalid_record_proposal','blank reason rejected');
select lives_ok($$select private.prepare_mcp_record_edit('18200000-0000-0000-0000-000000000002','18200000-0000-0000-0000-000000000007',(select current_version from public.reports where id='18200000-0000-0000-0000-000000000007'),'{"note":"after"}','reason')$$,'authorized proposal is created');
select is((select data->>'note' from public.report_values where report_id='18200000-0000-0000-0000-000000000007'),'before','preparing proposal does not change record');
select is((select before_content->'values'->>'note' from private.mcp_record_edit_proposals where report_id='18200000-0000-0000-0000-000000000007' and reason='reason' limit 1),'before','proposal stores before content');
select is((select proposed_content->'values'->>'note' from private.mcp_record_edit_proposals where report_id='18200000-0000-0000-0000-000000000007' and reason='reason' limit 1),'after','proposal stores proposed content');
select is((select original_snapshot = private.mcp_record_edit_snapshot(organization_id,report_id) from private.mcp_record_edit_proposals where report_id='18200000-0000-0000-0000-000000000007' and reason='reason' limit 1),true,'fresh proposal matches current snapshot');
savepoint renamed;
update public.clients set name='Renamed synthetic client' where id='18200000-0000-0000-0000-000000000006';
select is((select reference_content = private.mcp_record_edit_references(organization_id,report_id,proposed_content) from private.mcp_record_edit_proposals where report_id='18200000-0000-0000-0000-000000000007' and reason='reason' limit 1),false,'changed client identity invalidates reference snapshot');
rollback to savepoint renamed;
update public.report_values set data='{"note":"changed by another editor"}' where report_id='18200000-0000-0000-0000-000000000007';
select is((select original_snapshot = private.mcp_record_edit_snapshot(organization_id,report_id) from private.mcp_record_edit_proposals where report_id='18200000-0000-0000-0000-000000000007' and reason='reason' limit 1),false,'changes to report values alter snapshot');
insert into public.staffs(id,organization_id,name) values ('18200000-0000-0000-0000-000000000008','18200000-0000-0000-0000-000000000002','Synthetic staff');
insert into public.report_actual_staffs(report_id,staff_id,sort_order) values ('18200000-0000-0000-0000-000000000007','18200000-0000-0000-0000-000000000008',0);
select lives_ok($$select private.prepare_mcp_record_edit('18200000-0000-0000-0000-000000000002','18200000-0000-0000-0000-000000000007',(select current_version from public.reports where id='18200000-0000-0000-0000-000000000007'),'{"note":"changed by another editor"}','time update','{"start_at":"2026-10-28T01:30:00Z"}')$$,'time-only change is accepted');
select throws_ok($$select private.prepare_mcp_record_edit('18200000-0000-0000-0000-000000000002','18200000-0000-0000-0000-000000000007',(select current_version from public.reports where id='18200000-0000-0000-0000-000000000007'),'{"note":"changed by another editor"}','bad time','{"start_at":"2026-10-28T03:00:00Z"}')$$,'22023','invalid_record_proposal','end before start is rejected');
select throws_ok($$select private.prepare_mcp_record_edit('18200000-0000-0000-0000-000000000002','18200000-0000-0000-0000-000000000007',(select current_version from public.reports where id='18200000-0000-0000-0000-000000000007'),'{"note":"changed by another editor"}','bad staff','{"actual_staffs":[{"staff_id":"18200000-0000-0000-0000-000000000008"},{"staff_id":"18200000-0000-0000-0000-000000000008"}]}')$$,'22023','invalid_record_proposal','duplicate staff rejected');
select lives_ok($$select private.prepare_mcp_record_edit('18200000-0000-0000-0000-000000000002','18200000-0000-0000-0000-000000000007',(select current_version from public.reports where id='18200000-0000-0000-0000-000000000007'),'{"note":"changed by another editor","travel_expenses":[{"staff_id":"18200000-0000-0000-0000-000000000008","staff_name":"untrusted","method":"car","amount_yen":300}],"travel_cost_yen":300}','travel update')$$,'valid staff travel cost accepted');
select is((select proposed_content->'values'->'travel_expenses'->0->>'staff_name' from private.mcp_record_edit_proposals where reason='travel update'),'Synthetic staff','staff name is resolved from the organization');
select throws_ok($$select private.prepare_mcp_record_edit('18200000-0000-0000-0000-000000000002','18200000-0000-0000-0000-000000000007',(select current_version from public.reports where id='18200000-0000-0000-0000-000000000007'),'{"travel_expenses":[{"staff_id":"18200000-0000-0000-0000-000000000008","staff_name":"Synthetic staff","method":"car","amount_yen":300}],"travel_cost_yen":301}','bad total')$$,'22023','invalid_record_proposal','mismatched total rejected');
select throws_ok($$select private.prepare_mcp_record_edit('18200000-0000-0000-0000-000000000002','18200000-0000-0000-0000-000000000007',(select current_version from public.reports where id='18200000-0000-0000-0000-000000000007'),'{"travel_expenses":[{"staff_id":"18200000-0000-0000-0000-000000000099","staff_name":"Synthetic staff","method":"car","amount_yen":300}],"travel_cost_yen":300}','bad staff')$$,'22023','invalid_record_proposal','unassigned staff expense rejected');
select throws_ok($$select private.prepare_mcp_record_edit('18200000-0000-0000-0000-000000000002','18200000-0000-0000-0000-000000000007',(select current_version from public.reports where id='18200000-0000-0000-0000-000000000007'),'{"travel_expenses":[{"staff_id":"18200000-0000-0000-0000-000000000008","staff_name":"Synthetic staff","method":"none","amount_yen":300}],"travel_cost_yen":300}','invalid method amount')$$,'22023','invalid_record_proposal','none with nonzero amount rejected');
savepoint assigned_scope;
update public.organization_members set role='member' where organization_id='18200000-0000-0000-0000-000000000002' and user_id='18200000-0000-0000-0000-000000000001';
insert into public.organization_roles(id,organization_id,name,permissions) values ('18200000-0000-0000-0000-000000000010','18200000-0000-0000-0000-000000000002','Synthetic assigned','{"records":{"view":"all","edit":"assigned"}}');
insert into public.organization_member_roles(organization_id,user_id,role_id) values ('18200000-0000-0000-0000-000000000002','18200000-0000-0000-0000-000000000001','18200000-0000-0000-0000-000000000010');
select throws_ok($$select private.prepare_mcp_record_edit('18200000-0000-0000-0000-000000000002','18200000-0000-0000-0000-000000000007',(select current_version from public.reports where id='18200000-0000-0000-0000-000000000007'),'{"note":"assigned edit"}','assigned')$$,'42501','proposal_unavailable','assigned editor cannot edit unassigned client');
insert into public.assignments(client_id,helper_id) values ('18200000-0000-0000-0000-000000000006','18200000-0000-0000-0000-000000000001');
select lives_ok($$select private.prepare_mcp_record_edit('18200000-0000-0000-0000-000000000002','18200000-0000-0000-0000-000000000007',(select current_version from public.reports where id='18200000-0000-0000-0000-000000000007'),'{"note":"assigned edit"}','assigned')$$,'assigned editor can propose for assigned client');
update public.organization_roles set permissions='{"records":{"view":"all","edit":"none"}}' where id='18200000-0000-0000-0000-000000000010';
select throws_ok($$select private.prepare_mcp_record_edit('18200000-0000-0000-0000-000000000002','18200000-0000-0000-0000-000000000007',(select current_version from public.reports where id='18200000-0000-0000-0000-000000000007'),'{"note":"no edit"}','no edit')$$,'42501','proposal_unavailable','reader without edit cannot propose');
rollback to savepoint assigned_scope;
update public.reports set status='approved' where id='18200000-0000-0000-0000-000000000007';
select lives_ok($$select private.prepare_mcp_record_edit('18200000-0000-0000-0000-000000000002','18200000-0000-0000-0000-000000000007',(select current_version from public.reports where id='18200000-0000-0000-0000-000000000007'),'{"note":"correction proposal"}','reason')$$,'approved record can be proposed for correction');
select is((select data->>'note' from public.report_values where report_id='18200000-0000-0000-0000-000000000007'),'changed by another editor','correction proposal leaves approved original intact');
insert into public.clients(id,organization_id,name) values ('18200000-0000-0000-0000-000000000011','18200000-0000-0000-0000-000000000002','Synthetic default form client');
insert into public.reports(id,client_id,helper_id,service_date,status,start_at,end_at) values ('18200000-0000-0000-0000-000000000012','18200000-0000-0000-0000-000000000011','18200000-0000-0000-0000-000000000001','2026-10-28','draft','2026-10-28 01:00+00','2026-10-28 02:00+00');
select lives_ok($$select private.prepare_mcp_record_edit('18200000-0000-0000-0000-000000000002','18200000-0000-0000-0000-000000000012',(select current_version from public.reports where id='18200000-0000-0000-0000-000000000012'),'{"special_note":"synthetic"}','reason')$$,'default form and missing values row are supported');
select * from finish();
rollback;
